  UNION ALL
  SELECT f.item, 1000+f.ord FROM jsonb_array_elements(s.fields) WITH ORDINALITY f(item,ord)
  WHERE NOT EXISTS (SELECT 1 FROM canonical c WHERE c.item->>'key'=f.item->>'key')
    AND f.item->>'key' NOT IN ('job','hometown','personality','participationStartYear','childrenStartYear','youthStartYear','congregationStartYear','nickname','schoolClass','parentName','relativePhone')
 ) combined
),version=GREATEST(version,15) WHERE group_id='congregation';
COMMIT;
